import com.wolinski.shop.platform.ShopProblem;

/**
 * A discount percentage as whole basis points (12.5% is 1250), and the discount it gives on an amount.
 * ADR 8: no floating point and no BigDecimal; text is converted by hand.
 */
final class DiscountRate {

    static final String INVALID = "INVALID_DISCOUNT";

    private static final long ONE_HUNDRED_PERCENT = 10_000;

    private DiscountRate() {
    }

    /** Parses "0" to "100" with at most two decimals, e.g. "12", "12.5", "12.50". */
    static long parseBasisPoints(String text) {
        String s = text == null ? "" : text.trim();
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot);
        String fraction = dot < 0 ? "" : s.substring(dot + 1);

        if (whole.isEmpty() || whole.length() > 3 || !allDigits(whole)) {
            throw invalid(text);
        }
        if (dot >= 0 && (fraction.isEmpty() || fraction.length() > 2 || !allDigits(fraction))) {
            throw invalid(text);
        }

        long basisPoints = Long.parseLong(whole) * 100;
        if (fraction.length() == 1) {
            basisPoints += Long.parseLong(fraction) * 10;
        } else if (fraction.length() == 2) {
            basisPoints += Long.parseLong(fraction);
        }
        if (basisPoints > ONE_HUNDRED_PERCENT) {
            throw invalid(text);
        }
        return basisPoints;
    }

    /**
     * The discount on {@code minorUnits} at {@code basisPoints}, rounded half up to a minor unit.
     * Expects a non-negative amount. Splitting the amount into quotient and remainder keeps every
     * intermediate value within a long.
     */
    static long discountOf(long minorUnits, long basisPoints) {
        long quotient = minorUnits / ONE_HUNDRED_PERCENT;
        long remainder = minorUnits % ONE_HUNDRED_PERCENT;
        return quotient * basisPoints + (remainder * basisPoints + ONE_HUNDRED_PERCENT / 2) / ONE_HUNDRED_PERCENT;
    }

    private static boolean allDigits(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static ShopProblem invalid(String text) {
        return new ShopProblem(INVALID, "Discount must be a percentage from 0 to 100 with at most two decimals: " + text);
    }
}
}

