import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.ShopConfig;
import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.platform.ShopProblem;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderDiscountTest {

    @Test
    void textIsReadAsBasisPoints() {
        assertEquals(1250, DiscountRate.parseBasisPoints("12.5"));
        assertEquals(1250, DiscountRate.parseBasisPoints("12.50"));
        assertEquals(1200, DiscountRate.parseBasisPoints("12"));
        assertEquals(50, DiscountRate.parseBasisPoints("0.5"));
        assertEquals(1, DiscountRate.parseBasisPoints("0.01"));
        assertEquals(0, DiscountRate.parseBasisPoints("0"));
        assertEquals(10_000, DiscountRate.parseBasisPoints("100"));
        assertEquals(1250, DiscountRate.parseBasisPoints(" 12.5 "));
    }

    @Test
    void malformedOrOutOfRangeTextIsRefused() {
        for (String text : new String[] {null, "", " ", "abc", "-1", "+1", "1e2", "1,5", "12.", ".5",
                "12.345", "1000", "100.01", "101"}) {
            ShopProblem problem = assertThrows(ShopProblem.class, () -> DiscountRate.parseBasisPoints(text), text);
            assertEquals("INVALID_DISCOUNT", problem.code());
        }
    }

    @Test
    void discountRoundsHalfUpToAMinorUnit() {
        assertEquals(1, DiscountRate.discountOf(100, 50));    // 0.5% of 1.00 PLN is 0.01 PLN
        assertEquals(125, DiscountRate.discountOf(1000, 1250)); // exact
        assertEquals(125, DiscountRate.discountOf(1001, 1250)); // 125.125 rounds down
        assertEquals(1, DiscountRate.discountOf(50, 100));    // 0.5 rounds up
        assertEquals(0, DiscountRate.discountOf(49, 100));    // 0.49 rounds down
        assertEquals(1, DiscountRate.discountOf(1, 10_000));  // 100% of one unit
        assertEquals(0, DiscountRate.discountOf(0, 10_000));
    }

    @Test
    void largeAmountsDoNotOverflow() {
        long big = 9_000_000_000_000_000_000L;
        assertEquals(big, DiscountRate.discountOf(big, 10_000));
        assertEquals(big / 2, DiscountRate.discountOf(big, 5_000));
    }

    @Test
    void theFacadeLowersTheTotal() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z"));

            orders.applyDiscount(id, "0.5");

            assertEquals(Money.pln(99), orders.summary(id).total());
        }
    }

    @Test
    void aRefusedDiscountLeavesTheTotalAlone() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, "12.345"));

            assertEquals(Money.pln(1000), orders.summary(id).total());
        }
    }
}
}
